26	// hashEnvelope is the historical fingerprint envelope struct the legacy
27	// JSON fingerprint family was computed over. Production no longer names
28	// it — the single record field table (record_fields.go) defines the
29	// envelope now — but the tests keep it as an independent oracle: if the
30	// table-driven JSON encoder ever drifted from the historical
31	// encoding/json output, the comparisons against legacyJSONFingerprint
32	// would catch it.
33	type hashEnvelope struct {
34		Org             string          `json:"org"`
35		Seq             int             `json:"seq"`
36		Kind            string          `json:"kind"`
