376			{"record kind", func(r []AuditRecord, repl string) {
377				r[1].Kind += repl
378			}},
379			{"policy id", func(r []AuditRecord, repl string) {
380				p := &r[0].Change.Policies[0]
381				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
382			}},
383			{"policy subject", func(r []AuditRecord, repl string) {
384				p := &r[0].Change.Policies[0]
385				p.Subject = strings.Replace(p.Subject, invalidByte, repl, 1)
386			}},
387			{"policy action", func(r []AuditRecord, repl string) {
388				p := &r[0].Change.Policies[0]
389				p.Action = strings.Replace(p.Action, invalidByte, repl, 1)
390			}},
391			{"policy scope", func(r []AuditRecord, repl string) {
392				p := &r[0].Change.Policies[0]
393				p.Scope = strings.Replace(p.Scope, invalidByte, repl, 1)
394			}},
395			{"policy effect", func(r []AuditRecord, repl string) {
396				p := &r[0].Change.Policies[0]
397				p.Effect = Effect(string(p.Effect) + repl)
398			}},
399			{"second policy in list", func(r []AuditRecord, repl string) {
400				p := &r[0].Change.Policies[1]
401				p.ID = strings.Replace(p.ID, invalidByte, repl, 1)
402			}},
403			{"subject org", func(r []AuditRecord, repl string) {
404				r[1].Decision.Request.SubjectOrg = strings.Replace(r[1].Decision.Request.SubjectOrg, invalidByte, repl, 1)
405			}},
406			{"resource org", func(r []AuditRecord, repl string) {
407				r[1].Decision.Request.ResourceOrg = strings.Replace(r[1].Decision.Request.ResourceOrg, invalidByte, repl, 1)
408			}},
409			{"subject id between chinese", func(r []AuditRecord, repl string) {
410				id := &r[1].Decision.Request.Subject.ID
411				*id = strings.Replace(*id, invalidByte, repl, 1)
412			}},
413			{"subject kind", func(r []AuditRecord, repl string) {
414				r[1].Decision.Request.Subject.Kind = strings.Replace(r[1].Decision.Request.Subject.Kind, invalidByte, repl, 1)
415			}},
416			{"first role in list", func(r []AuditRecord, repl string) {
417				roles := r[1].Decision.Request.Subject.Roles
418				roles[0] = strings.Replace(roles[0], invalidByte, repl, 1)
419			}},
420			{"second role in list", func(r []AuditRecord, repl string) {
421				r[1].Decision.Request.Subject.Roles[1] += repl
422			}},
423			{"resource id", func(r []AuditRecord, repl string) {
424				r[1].Decision.Request.Resource.ID = strings.Replace(r[1].Decision.Request.Resource.ID, invalidByte, repl, 1)
425			}},
