// One-time generator for the frozen offline-review compatibility material.
// Run once, paste the output into the compat test, then delete.
package main

import (
	"encoding/hex"
	"fmt"

	ds "github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	s := ds.NewStore()

	// seq 1: publish v1 — plain-text allow policy restricted to resource r1.
	p1 := ds.Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: ds.EffectAllow, ResourceID: "r1"}
	if _, err := s.Publish("acme", 0, []ds.Policy{p1}); err != nil {
		panic(err)
	}

	// seq 2: TARGET decision — request resource r1 matches the restriction.
	// Roles not provided (nil); Kind carries a genuine U+FFFD (valid UTF-8).
	target := ds.OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject:     ds.Subject{ID: "u1", Kind: "外�部"},
		Resource:    ds.Resource{ID: "r1", Scope: "org/a"},
		Action:      "read",
	}
	d := s.Decide("acme", target)
	fmt.Printf("target decision: %+v\n", d)

	// seq 3: publish v2 — policy carrying lone 0xFF bytes (invalid UTF-8).
	p2 := ds.Policy{ID: "策\xff略", Subject: "用\xff戶", Action: "读\xff", Scope: "org/a/资\xff料", Effect: ds.EffectAllow}
	if _, err := s.Publish("acme", 1, []ds.Policy{p2}); err != nil {
		panic(err)
	}

	// seq 4: invalid-byte decision; Roles explicitly empty (non-nil).
	req2 := ds.OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject:     ds.Subject{ID: "用\xff戶", Kind: "类\xff型", Roles: []string{}},
		Resource:    ds.Resource{ID: "资\xff源", Scope: "org/a/资\xff料"},
		Action:      "读\xff",
	}
	d2 := s.Decide("acme", req2)
	fmt.Printf("second decision: %+v\n", d2)

	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		panic(err)
	}
	archive, err := ds.EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		panic(err)
	}

	fmt.Printf("checkpoint: endSeq=%d fingerprint=%s\n", cp.EndSeq, cp.Fingerprint)
	for _, r := range recs {
		fmt.Printf("seq=%d kind=%s\n  prev=%s\n  fp=%s\n", r.Seq, r.Kind, r.PrevFingerprint, r.Fingerprint)
	}
	fmt.Printf("archive hex (%d bytes):\n%s\n", len(archive), hex.EncodeToString(archive))
}

